        "method": "Создать файл 'папка/файл.json' → папка создастся сама",
        "steps": [
          "1. НЕ нужно сначала создавать папку отдельно",
          "2. Создай файл по пути 'папка/файл.json' — папка создастся сама",
          "3. GitHub автоматически сформирует дерево директорий"
        ],
        "example": {
          "file_path": "skills/writing.json",
          "content": "{\"identity\":{\"module_id\":\"SKILL-WRITING-001\",\"name\":\"Навык письма\",\"version\":\"1.0\",\"created\":\"2026-03-02\"},\"meta\":{\"description\":\"Навыки написания текстов\",\"status\":\"active\",\"tags\":[\"skills\",\"writing\"]},\"entries\":[]}",
          "description": "Создание папки 'skills/' с первым файлом writing.json",
          "result": "Папка skills/ создана, файл writing.json внутри — всё за один патч"
        }
      }
    },
    {
      "op": "add",
      "path": "content/creating_module",
      "value": {
        "title": "🧩 Создание нового модуля",
        "mandatory_structure": {
          "identity": {
            "module_id": "УНИКАЛЬНЫЙ-ID (например TASKS-001)",
            "name": "Название модуля",
            "version": "1.0",
            "created": "YYYY-MM-DD"
          },
          "meta": {
            "description": "Что делает модуль",
            "status": "active | draft",
            "tags": ["тег1", "тег2"]
          }
        },
        "patch_format": {
          "file_path": "honeycombs/новая-сота/index.json",
          "content": "{минифицированный JSON — без \\n и лишних пробелов}",
          "description": "Создание нового модуля в сотах"
        },
        "minification_rule": "ОБЯЗАТЕЛЬНО: content должен быть минифицирован. Используй json.dumps(data, separators=(',',':')) или убери все \\n и пробелы вручную.",
        "example": {
          "patch": {
            "file_path": "honeycombs/rituals/index.json",
            "content": "{\"identity\":{\"module_id\":\"RITUALS-001\",\"name\":\"Ритуалы\",\"version\":\"1.0\",\"created\":\"2026-03-02\"},\"meta\":{\"description\":\"Ритуалы и практики Мандалы\",\"status\":\"active\",\"tags\":[\"rituals\",\"core\"]},\"rituals\":[],\"registry\":{\"total\":0,\"active\":0}}",
            "description": "Создание соты ритуалов"
          }
        }
      }
    },
    {
      "op": "add",
      "path": "content/after_creating_module",
      "value": {
        "title": "✅ Что делать ПОСЛЕ создания модуля",
        "required_steps": [
          {
            "step": 1,
            "action": "Прочитай honeycombs/core_map/index.json",
            "how": "read_file('honeycombs/core_map/index.json')",
            "why": "Нужно знать ТОЧНУЮ структуру перед изменением"
          },
          {
            "step": 2,
            "action": "Добавь новый модуль в core_map/index.json",
            "how": "json_patch на honeycombs/core_map/index",
            "patch_example": {
              "target_module": "honeycombs/core_map/index",
              "description": "Регистрация новой соты в карте",
              "changes": [
                {
                  "op": "add",
                  "path": "honeycombs.rituals",
                  "value": {
                    "description": "Ритуалы и практики Мандалы",
                    "status": "active",
                    "type": "core"
                  }
                }
              ]
            }
          }
        ],
        "auto_registration": "⚠️ Система автоматически добавит новый .json модуль из simbiosis/ в kernel.module_list при создании (см. handle_apply_patch в main.py). Для сот — нужно добавить вручную в core_map через патч."
      }
    },
    {
      "op": "add",
      "path": "content/creating_module_in_new_folder",
      "value": {
        "title": "📂 Создание модуля в НОВОЙ папке (вне сот)",
        "important": "Новая папка за пределами honeycombs/ — например 'docs/', 'tools/', 'skills/' — не попадёт в ядро автоматически.",
        "workflow": [
          "1. Создай файл через full_replacement: 'docs/overview.md' или 'tools/helper.json'",
          "2. GitHub создаст папку автоматически",
          "3. Если нужно включить в ядро — добавь в kernel.on_demand_modules через патч в main.py",
          "4. Зарегистрируй в core_map.json"
        ],
        "example_multi_patch": {
          "description": "Создать папку docs/ с первым файлом и зарегистрировать в core_map",
          "patches": [
            {
              "file_path": "docs/architecture.md",
              "content": "# Архитектура Мандалы\n\nОписание архитектуры системы.\n",
              "description": "Создание папки docs/ с файлом архитектуры"
            },
            {
              "target_module": "honeycombs/core_map/index",
              "description": "Регистрация docs/ в карте репозитория",
              "changes": [
                {
                  "op": "add",
                  "path": "repository.files.docs_architecture_md",
                  "value": {
                    "description": "Описание архитектуры системы",
                    "type": "documentation"
                  }
                }
              ]
            }
          ]
        }
      }
    },
    {
      "op": "update",
      "path": "content/patch_types",
      "value": {
        "full_replacement": {
          "use": "Создание нового файла или полная замена существующего",
          "required_fields": ["file_path", "content", "description"],
          "note": "content ДОЛЖЕН быть минифицированным JSON или чистым текстом",
          "example": "Создание папки 'skills/' с файлом 'writing.json'"
        },
        "json_patch": {
          "use": "Точечные изменения в существующем .json файле",
          "required_fields": ["target_module", "changes"],
          "note": "target_module БЕЗ расширения .json: 'honeycombs/seeds/index' (не 'honeycombs/seeds/index.json')",
          "example": "Обновление карты сот после создания новой соты"
        },
        "text_patch": {
          "use": "Замены строк в .py, .html, .md файлах",
          "required_fields": ["file_path", "replacements"],
          "note": "Строка в 'old' должна встречаться РОВНО 1 РАЗ",
          "example": "Добавление кнопки модуля в меню инженерного чата"
        },
        "multi_patch": {
          "use": "Изменения в нескольких файлах за один раз",
          "format": {
            "patches": ["массив патчей любых типов выше"]
          },
          "example": "Создать модуль + зарегистрировать в core_map за один запрос"
        }
      }
    },
    {
      "op": "update",
      "path": "checklist",
      "value": [
        "[ ] Обсудил с Садовником — модуль/папка действительно нужна?",
        "[ ] Придумал осмысленный ID и имя?",
        "[ ] Подготовил минимальную структуру (не раздутую)?",
        "[ ] content МИНИФИЦИРОВАН (нет \\n)?",
        "[ ] Размер content < 20KB?",
        "[ ] Готов патч для core_map/index.json после создания?",
        "[ ] Нужна кнопка в меню? Готов патч для index.html?",
        "[ ] Прочитал core_map/index.json через read_file перед изменением?"
      ]
    },
    {
      "op": "add",
      "path": "common_errors",
      "value": {
        "title": "❌ Частые ошибки при создании",
        "errors": [
          {
            "mistake": "Пытаться создать пустую папку",
            "symptom": "Нет такого API в GitHub",
            "fix": "Создай файл внутри папки — папка появится сама"
          },
          {
            "mistake": "content не минифицирован",
            "symptom": "Патч обрезается при >20KB",
            "fix": "Убери все \\n и лишние пробелы из content"
