            "content": "{\"identity\":{\"module_id\":\"METRICS-001\",\"name\":\"Метрики\",\"version\":\"1.0\",\"created\":\"2026-03-03\"},\"meta\":{\"description\":\"Метрики и аналитика Мандалы\",\"status\":\"active\",\"tags\":[\"metrics\",\"analytics\"]},\"metrics\":[],\"dashboard\":{}}",
            "description": "Создание соты метрик"
